export const TRACKS = [{"id": "python", "name": "Python", "subtitle": "Le basi che fanno la differenza", "icon": "code", "color": "#427d69", "tint": "#e8f2eb", "topics": "Funzioni · liste · dizionari · closure", "description": "Impara a ragionare in Python: parti da piccole funzioni, poi combina strutture dati e astrazioni."}, {"id": "algorithms", "name": "Algoritmi", "subtitle": "Un problema, un passo alla volta", "icon": "branch", "color": "#c27a36", "tint": "#fbefde", "topics": "Ricerca · complessità · grafi", "description": "Scomponi i problemi, riconosci i pattern e scegli strutture dati adatte. Nessuna gara contro il tempo."}, {"id": "data", "name": "Dati & NumPy", "subtitle": "Dai numeri alle informazioni", "icon": "chart", "color": "#557eb2", "tint": "#eaf0fa", "topics": "Array · filtri · statistiche", "description": "Pulisci, riassumi e trasformi piccoli dataset. NumPy è incluso e funziona anche offline."}, {"id": "ml", "name": "Machine learning", "subtitle": "Costruisci il tuo primo modello", "icon": "spark", "color": "#a07750", "tint": "#f6efdf", "topics": "Metriche · regressione · kNN", "description": "Scrivi i mattoni di un modello e capisci cosa misurano. Gli esempi usano dataset piccoli e leggibili."}, {"id": "dl", "name": "Deep learning", "subtitle": "Dentro una rete neurale", "icon": "network", "color": "#aa6b80", "tint": "#f8ebef", "topics": "Neuroni · attivazioni · gradienti", "description": "Dai prodotti scalari al backpropagation: una rete neurale spiegata attraverso funzioni Python."}, {"id": "rl", "name": "Reinforcement learning", "subtitle": "Imparare dalle conseguenze", "icon": "target", "color": "#538d95", "tint": "#e8f3f4", "topics": "Reward · bandit · Q-learning", "description": "Implementa ricompense, esplorazione e aggiornamenti del valore. Ogni formula viene spiegata nei suoi passaggi."}, {"id": "automation", "name": "Automazione", "subtitle": "Python nella vita vera", "icon": "bolt", "color": "#868145", "tint": "#f3f1e1", "topics": "Testo · CSV · JSON · batch", "description": "Trasforma attività ripetitive in piccole funzioni riutilizzabili, senza accedere ai file del telefono."}];
export const LESSONS = [{"id": "functions", "track": "python", "title": "Una funzione, un risultato", "minutes": 3, "intro": "Una funzione è un piccolo contratto: riceve dei dati e restituisce una risposta.", "sections": [{"title": "Ingresso e uscita", "text": "Il parametro è un nome locale per il dato in ingresso. Con return consegni il risultato a chi ha chiamato la funzione. print mostra un messaggio, ma non restituisce quel valore.", "code": "def doppio(numero):\n    return numero * 2\n\nrisultato = doppio(7)  # 14"}, {"title": "Dal caso concreto alla regola", "text": "Prova prima un esempio a mano. Per 7 il risultato è 14; per 0 è 0. Poi scrivi la stessa regola usando il parametro, senza fissare il numero 7 nel codice.", "code": ""}, {"title": "Controlla i casi ai bordi", "text": "Un numero negativo è comunque un numero. Una lista vuota è comunque una lista. I test ai bordi ti dicono se la tua regola è generale.", "code": ""}], "quiz": {"question": "Cosa riceve chi chiama una funzione che usa solo print(4)?", "choices": ["Il numero 4", "None", "La stringa \"4\""], "answer": 1, "explanation": "Senza un return esplicito, Python restituisce None. Il messaggio stampato è un effetto separato."}}, {"id": "loops", "track": "python", "title": "Liste, cicli e comprehension", "minutes": 4, "intro": "Un ciclo applica un ragionamento a ogni elemento. Una comprehension esprime una trasformazione semplice in una riga.", "sections": [{"title": "Accumula un risultato", "text": "Inizia dal valore neutro: 0 per una somma, [] per una nuova lista. A ogni passaggio aggiorni il risultato.", "code": "totale = 0\nfor numero in [2, 4, 6]:\n    totale += numero"}, {"title": "Trasforma o filtra", "text": "La parte prima di for dice cosa produrre. La condizione dopo if dice quali elementi tenere. Un filtro non cambia da solo il valore degli elementi.", "code": "quadrati = [x * x for x in [1, 2, 3]]\npositivi = [x for x in [-1, 0, 2] if x > 0]"}, {"title": "Usa la forma che capisci", "text": "Una comprehension non è obbligatoria. Se il ragionamento ha diversi passaggi, un ciclo esplicito spesso si legge meglio.", "code": ""}], "quiz": {"question": "Qual è il risultato di [x * 2 for x in [1, 3] if x > 1]?", "choices": ["[2, 6]", "[3]", "[6]"], "answer": 2, "explanation": "Il filtro elimina 1. L’unico elemento rimasto, 3, viene poi moltiplicato per 2."}}, {"id": "dicts", "track": "python", "title": "Dizionari: contare e raggruppare", "minutes": 4, "intro": "Un dizionario collega una chiave a un valore. È utile quando vuoi ritrovare un risultato per nome.", "sections": [{"title": "Chiave e valore", "text": "In {\"mele\": 3}, la chiave è \"mele\" e il valore è 3. Una chiave compare una volta sola, ma puoi aggiornare il suo valore.", "code": "conteggi = {}\nfor parola in [\"ciao\", \"ciao\", \"ok\"]:\n    conteggi[parola] = conteggi.get(parola, 0) + 1"}, {"title": "Quando una chiave manca", "text": "get(chiave, valore_predefinito) evita un errore quando la chiave non è ancora presente. Per raggruppare, il valore può essere una lista.", "code": "gruppi = {}\nfor nome, categoria in [(\"A\", \"blu\"), (\"B\", \"blu\")]:\n    gruppi.setdefault(categoria, []).append(nome)"}, {"title": "Ordine e identità", "text": "Un set ti aiuta a riconoscere i duplicati. Una lista separata conserva l’ordine dei primi incontri.", "code": ""}], "quiz": {"question": "Cosa restituisce {}.get(\"x\", 0)?", "choices": ["Un errore", "0", "\"x\""], "answer": 1, "explanation": "La chiave non esiste, quindi get restituisce il valore predefinito 0."}}, {"id": "advanced-python", "track": "python", "title": "Closure e strutture annidate", "minutes": 5, "intro": "Puoi combinare funzioni e strutture dati: ogni livello aggiunge un pezzo del problema.", "sections": [{"title": "Una funzione può restituire una funzione", "text": "La funzione interna può ricordare un parametro della funzione esterna. Questa combinazione si chiama closure.", "code": "def aggiungi(n):\n    def applica(x):\n        return x + n\n    return applica\n\npiu_tre = aggiungi(3)\npiu_tre(8)  # 11"}, {"title": "Appiattisci un livello", "text": "Per trasformare una lista di liste in una sola lista, visita la lista esterna e poi gli elementi della lista interna.", "code": "piatta = []\nfor gruppo in [[1, 2], [3]]:\n    for valore in gruppo:\n        piatta.append(valore)"}, {"title": "Annotazioni facoltative", "text": "Un type hint documenta il tipo previsto; non converte automaticamente i dati e non sostituisce i test.", "code": "def doppio(x: int) -> int:\n    return 2 * x"}], "quiz": {"question": "Che cosa ricorda la funzione restituita da aggiungi(3)?", "choices": ["Il valore di n, cioè 3", "Ogni valore futuro di x", "Niente"], "answer": 0, "explanation": "La closure mantiene il riferimento al parametro n dello scope esterno."}}, {"id": "search", "track": "algorithms", "title": "Ricerca e casi limite", "minutes": 4, "intro": "Prima di ottimizzare, definisci cosa significa trovare una risposta e cosa restituire quando non esiste.", "sections": [{"title": "Ricerca lineare", "text": "Visita gli elementi in ordine e fermati al primo che soddisfa la richiesta. Se non trovi nulla, restituisci il valore concordato, per esempio -1.", "code": "def cerca(valori, obiettivo):\n    for i, valore in enumerate(valori):\n        if valore == obiettivo:\n            return i\n    return -1"}, {"title": "Due puntatori", "text": "Due indici possono muoversi nello stesso contenitore: uno da sinistra e uno da destra. Per controllare un palindromo confronti le coppie simmetriche.", "code": ""}, {"title": "Le condizioni contano", "text": "Decidi in anticipo come gestire lista vuota, duplicati e risultato assente. Non esiste una sola convenzione universale.", "code": ""}], "quiz": {"question": "In una ricerca lineare, quanto lavoro serve nel caso peggiore su n elementi?", "choices": ["Circa n confronti", "Sempre un confronto", "Sempre n² confronti"], "answer": 0, "explanation": "Se il valore manca o è in fondo, puoi dover visitare tutti gli n elementi."}}, {"id": "patterns", "track": "algorithms", "title": "Set, stack e ricerca binaria", "minutes": 5, "intro": "Una buona struttura dati elimina lavoro inutile.", "sections": [{"title": "Ricorda ciò che hai visto", "text": "Un set permette di verificare rapidamente se un elemento è già stato incontrato. Per la somma di due numeri, cerca il complemento: obiettivo meno valore corrente.", "code": "visti = set()\nfor x in [2, 7, 4]:\n    complemento = 9 - x\n    if complemento in visti:\n        print(\"coppia trovata\")\n    visti.add(x)"}, {"title": "Ultimo entrato, primo uscito", "text": "Uno stack è una pila. append aggiunge e pop rimuove l’ultimo elemento: perfetto per abbinare parentesi aperte e chiuse.", "code": ""}, {"title": "Dimezza solo se è ordinato", "text": "La ricerca binaria confronta il valore centrale e scarta metà dell’intervallo. Funziona perché la lista è ordinata.", "code": "sinistra, destra = 0, len(valori) - 1\ncentro = (sinistra + destra) // 2"}], "quiz": {"question": "Qual è il requisito essenziale per una ricerca binaria su una lista?", "choices": ["La lista deve essere ordinata", "Deve contenere solo numeri positivi", "Deve avere lunghezza pari"], "answer": 0, "explanation": "L’ordine permette di sapere quale metà non può contenere l’obiettivo."}}, {"id": "graphs", "track": "algorithms", "title": "Grafi, BFS e programmazione dinamica", "minutes": 6, "intro": "Alcuni problemi richiedono di ricordare gli stati già esplorati o le risposte a sottoproblemi.", "sections": [{"title": "BFS: visita a livelli", "text": "In un grafo non pesato, una coda visita prima i vicini, poi i vicini dei vicini. Il primo arrivo a un nodo ha il minor numero di archi.", "code": "from collections import deque\ncoda = deque([(inizio, 0)])\nvisitati = {inizio}"}, {"title": "Non esplorare due volte", "text": "Aggiungi un nodo ai visitati quando lo metti in coda. Senza questo controllo, un ciclo nel grafo può produrre lavoro infinito.", "code": ""}, {"title": "Costruisci dalle risposte piccole", "text": "La programmazione dinamica riutilizza risultati precedenti. Per contare salite da 1 o 2 gradini, modi(n) = modi(n-1) + modi(n-2).", "code": "modi = [1, 1]\n# 0 gradini: una sequenza vuota\n# 1 gradino: una salita da 1"}], "quiz": {"question": "Quando conviene segnare un nodo come visitato in BFS?", "choices": ["Quando lo inserisci in coda", "Dopo aver svuotato la coda", "Mai"], "answer": 0, "explanation": "Così eviti che due vicini inseriscano lo stesso nodo più volte."}}, {"id": "statistics", "track": "data", "title": "Media, varianza e dati mancanti", "minutes": 5, "intro": "Una statistica riassume dei dati. Prima del calcolo, stabilisci quali valori hanno un significato.", "sections": [{"title": "Media", "text": "Somma i valori e dividi per quanti sono. [2, 4, 6] ha somma 12 e contiene 3 valori, quindi la media è 4. Se non ci sono valori, la divisione non è definita: usa la convenzione dell’esercizio.", "code": "media = sum(valori) / len(valori)"}, {"title": "Varianza della popolazione", "text": "Calcola gli scarti dalla media, elevali al quadrato e fai la media dei quadrati. Per [2, 4, 6] ottieni (4 + 0 + 4) / 3 = 8/3. Il quadrato impedisce agli scarti positivi e negativi di annullarsi.", "code": "m = sum(valori) / len(valori)\nvarianza = sum((x - m) ** 2 for x in valori) / len(valori)"}, {"title": "None non è zero", "text": "Un valore mancante va escluso o imputato secondo una regola esplicita. Sostituirlo con zero senza motivo cambia il significato della media.", "code": "validi = [x for x in dati if x is not None]"}], "quiz": {"question": "Qual è la media di [2, None, 6] escludendo il valore mancante?", "choices": ["8/3", "4", "0"], "answer": 1, "explanation": "I valori validi sono due: (2 + 6) / 2 = 4."}}, {"id": "numpy", "track": "data", "title": "NumPy: array, assi e maschere", "minutes": 5, "intro": "Un array NumPy ti permette di applicare operazioni a tanti numeri insieme.", "sections": [{"title": "Operazioni elemento per elemento", "text": "Moltiplicare un array per 2 raddoppia ogni valore. Una lista Python moltiplicata per 2 invece si ripete.", "code": "import numpy as np\na = np.array([1, 2, 3])\n(a * 2).tolist()  # [2, 4, 6]"}, {"title": "Una maschera sceglie i valori", "text": "a > 2 produce un array di booleani. Usarlo tra parentesi quadre mantiene i valori nelle posizioni True.", "code": "a[a > 2].tolist()  # [3]"}, {"title": "Gli assi di una matrice", "text": "Per una matrice 2D, axis=0 riduce le righe e produce un risultato per colonna. axis=1 riduce le colonne e produce un risultato per riga.", "code": "m = np.array([[1, 2], [3, 4]])\nm.mean(axis=0).tolist()  # [2.0, 3.0]"}], "quiz": {"question": "Che risultato dà np.array([[1, 3], [5, 7]]).mean(axis=0)?", "choices": ["[2, 6]", "[3, 5]", "4"], "answer": 1, "explanation": "La prima colonna ha media 3; la seconda ha media 5."}}, {"id": "scaling", "track": "data", "title": "Normalizzare e raggruppare", "minutes": 5, "intro": "Trasformare i dati serve a rendere confrontabili valori con scale diverse.", "sections": [{"title": "Min-max, un passaggio alla volta", "text": "Sottrai il minimo per spostare l’inizio a zero. Poi dividi per massimo meno minimo per portare il valore più grande a uno. [10, 20, 30] diventa [0, 0.5, 1].", "code": "normalizzato = (x - minimo) / (massimo - minimo)"}, {"title": "Z-score", "text": "Sottrai la media e dividi per la deviazione standard. Lo zero indica il centro dei dati; un valore 2 indica due deviazioni standard sopra la media. Se tutti i valori sono uguali, la deviazione è zero: gestisci il caso.", "code": "z = (x - media) / deviazione_standard"}, {"title": "Group by", "text": "Raccogli una somma e un conteggio per ogni categoria. La media del gruppo è somma del gruppo diviso conteggio del gruppo.", "code": ""}], "quiz": {"question": "Cosa fai se massimo e minimo coincidono nella normalizzazione min-max?", "choices": ["Dividi comunque", "Gestisci il caso separatamente, per esempio con zeri", "Elimini sempre tutto il dataset"], "answer": 1, "explanation": "Il denominatore sarebbe zero. L’esercizio deve specificare quale valore restituire."}}, {"id": "metrics", "track": "ml", "title": "Misurare un modello", "minutes": 5, "intro": "Una previsione è utile se sai confrontarla con il risultato reale.", "sections": [{"title": "Accuracy", "text": "Conta quante etichette previste coincidono con le etichette reali, poi dividi per il numero di esempi. Non dice quali tipi di errore commetti.", "code": "accuracy = corretti / totale"}, {"title": "MSE", "text": "Per ogni esempio calcola previsione meno valore reale. Eleva lo scarto al quadrato, somma e dividi per il numero di esempi. Il quadrato penalizza di più gli errori grandi.", "code": "mse = sum((p - y) ** 2 for y, p in zip(reali, previsti)) / len(reali)"}, {"title": "Precision e recall", "text": "TP sono i positivi corretti, FP i positivi sbagliati, FN i positivi persi. Precision = TP/(TP+FP); recall = TP/(TP+FN). Se il denominatore è zero, qui usiamo 0.0.", "code": ""}], "quiz": {"question": "Un modello predice [1, 0, 1] e le etichette vere sono [1, 1, 1]. Qual è l’accuracy?", "choices": ["1/3", "2/3", "1"], "answer": 1, "explanation": "Due previsioni su tre coincidono con le etichette reali."}}, {"id": "regression", "track": "ml", "title": "Retta, loss e discesa del gradiente", "minutes": 6, "intro": "Un modello lineare usa una regola semplice: previsione = peso × ingresso + bias.", "sections": [{"title": "Peso e bias", "text": "Il peso decide quanto cambia la previsione quando x aumenta di uno. Il bias sposta tutta la retta. Con w=2 e b=1, x=3 produce 7.", "code": "previsione = w * x + b"}, {"title": "Il gradiente indica una direzione", "text": "Per la loss quadratica media, il gradiente rispetto a w è 2/n × somma((previsione − y) × x). Il fattore 2 viene dalla derivata del quadrato; 1/n dalla media.", "code": "errori = [w * x + b - y for x, y in zip(xs, ys)]\ngrad_w = 2 * sum(e * x for e, x in zip(errori, xs)) / len(xs)"}, {"title": "Aggiorna in direzione opposta", "text": "Sottrai learning_rate × gradiente. Se il gradiente è positivo, riduci w. Un learning rate troppo grande può far aumentare la loss.", "code": "w_nuovo = w - learning_rate * grad_w"}], "quiz": {"question": "Se w=3, gradiente=2 e learning rate=0.1, quanto vale il nuovo w?", "choices": ["3.2", "2.8", "1"], "answer": 1, "explanation": "3 − 0.1 × 2 = 2.8. Sottrai il passo, perché vuoi scendere lungo la loss."}}, {"id": "classification", "track": "ml", "title": "kNN, split e data leakage", "minutes": 5, "intro": "Un modello deve funzionare anche su dati che non ha già visto.", "sections": [{"title": "Vicini più simili", "text": "kNN calcola le distanze, prende i k esempi più vicini e usa le loro etichette. Per un esempio in 1D basta il valore assoluto della differenza.", "code": "distanza = abs(x_train - x_nuovo)"}, {"title": "Separare train e test", "text": "Usa il train per imparare parametri e trasformazioni. Usa il test per una valutazione finale. L’esercizio di split mantiene l’ordine per rendere i test riproducibili.", "code": ""}, {"title": "Evita la fuga di informazioni", "text": "Se normalizzi con statistiche calcolate anche sul test, il training ha già visto informazioni del test. Calcola le statistiche sul train e applicale a entrambi.", "code": ""}], "quiz": {"question": "Su quali dati dovresti calcolare la media di una trasformazione durante il training?", "choices": ["Train e test insieme", "Solo sul train", "Solo sul test"], "answer": 1, "explanation": "Includere il test trasferirebbe informazioni dalla valutazione al training: è data leakage."}}, {"id": "neurons", "track": "dl", "title": "Il neurone: somma e attivazione", "minutes": 4, "intro": "Un neurone combina gli ingressi e trasforma il risultato con una funzione di attivazione.", "sections": [{"title": "Prodotto scalare", "text": "Moltiplica ogni ingresso per il suo peso, poi somma. Infine aggiungi il bias. Con x=[2, 3], w=[1, 2], b=1 ottieni 2×1 + 3×2 + 1 = 9.", "code": "z = sum(xi * wi for xi, wi in zip(x, w)) + b"}, {"title": "ReLU", "text": "ReLU restituisce il massimo tra zero e z. Mantiene i numeri positivi e azzera quelli negativi.", "code": "relu = max(0, z)"}, {"title": "Sigmoid", "text": "Sigmoid(z) = 1 / (1 + exp(−z)). exp è la funzione esponenziale. Per z=0, exp(0)=1, quindi sigmoid(0)=1/2.", "code": "import math\np = 1 / (1 + math.exp(-z))"}], "quiz": {"question": "Quanto vale ReLU(-4)?", "choices": ["-4", "4", "0"], "answer": 2, "explanation": "ReLU conserva solo la parte positiva: max(0, -4) è 0."}}, {"id": "probabilities", "track": "dl", "title": "Softmax e cross-entropy", "minutes": 6, "intro": "Da punteggi grezzi puoi ottenere probabilità e misurare quanto penalizzare una previsione.", "sections": [{"title": "Softmax", "text": "Calcola l’esponenziale di ogni punteggio, poi dividi ciascun risultato per la somma degli esponenziali. Le probabilità sommano a 1.", "code": "esponenziali = [math.exp(x) for x in logits]\nprobabilita = [e / sum(esponenziali) for e in esponenziali]"}, {"title": "Stabilità numerica", "text": "Sottrarre il punteggio massimo prima dell’esponenziale non cambia il risultato della softmax e evita numeri troppo grandi.", "code": "m = max(logits)\nesponenziali = [math.exp(x - m) for x in logits]"}, {"title": "Cross-entropy binaria", "text": "Per un’etichetta y pari a 0 o 1: −[y log(p) + (1−y) log(1−p)]. Se y=1 resta −log(p): una probabilità alta produce una loss bassa. Evita log(0) con un piccolo epsilon.", "code": "p = min(max(p, 1e-12), 1 - 1e-12)"}], "quiz": {"question": "Perché sottrai il massimo dai logits prima della softmax?", "choices": ["Per cambiare la classe vincente", "Per migliorare la stabilità numerica", "Per ottenere sempre probabilità uguali"], "answer": 1, "explanation": "Gli esponenziali diventano più gestibili, mentre i rapporti finali restano uguali."}}, {"id": "backprop", "track": "dl", "title": "Gradienti e backpropagation", "minutes": 6, "intro": "La backpropagation applica la regola della catena per capire come ogni parametro influenza la loss.", "sections": [{"title": "Componi i passaggi", "text": "Per un neurone sigmoid con cross-entropy binaria, il gradiente del peso è (p − y) × x. p−y misura l’errore; x misura quanto l’ingresso influenza quel peso.", "code": "grad_w = (p - y) * x\nw = w - learning_rate * grad_w"}, {"title": "Più neuroni, stessa logica", "text": "Ogni neurone di uno strato dense usa un proprio vettore di pesi e un proprio bias. Calcoli una somma pesata per ognuno e poi l’attivazione.", "code": ""}, {"title": "Dropout con una maschera esplicita", "text": "In training, una maschera decide quali valori tenere. Nell’inverted dropout, dividi i valori rimasti per la probabilità di tenerli, per conservare la media attesa.", "code": "uscita = x * maschera / keep_probability"}], "quiz": {"question": "Con p=0.8, y=1 e x=2, quanto vale (p-y)×x?", "choices": ["0.4", "-0.4", "1.6"], "answer": 1, "explanation": "(0.8 − 1) × 2 = −0.4. Sottrarre questo gradiente fa crescere il peso."}}, {"id": "rewards", "track": "rl", "title": "Ricompense e ritorno scontato", "minutes": 5, "intro": "Nel reinforcement learning, un agente sceglie azioni e osserva ricompense.", "sections": [{"title": "Ricompensa e ritorno", "text": "La ricompensa riguarda un singolo passo. Il ritorno combina le ricompense future. Non sono la stessa quantità.", "code": ""}, {"title": "Il ruolo di gamma", "text": "Gamma (γ) è un numero tra 0 e 1. Il ritorno è r0 + γ×r1 + γ²×r2 + … . Una ricompensa più lontana viene moltiplicata più volte per γ.", "code": "ritorno = 0\nfor ricompensa in reversed(rewards):\n    ritorno = ricompensa + gamma * ritorno"}, {"title": "Un esempio concreto", "text": "Con ricompense [2, 4] e γ=0.5 ottieni 2 + 0.5×4 = 4. Con γ=0 contano solo le ricompense immediate.", "code": ""}], "quiz": {"question": "Qual è il ritorno di [1, 2, 4] con gamma=0.5?", "choices": ["7", "3", "1"], "answer": 1, "explanation": "1 + 0.5×2 + 0.25×4 = 3."}}, {"id": "exploration", "track": "rl", "title": "Esplorare: epsilon-greedy e UCB", "minutes": 5, "intro": "Se scegli sempre ciò che sembra migliore, potresti non scoprire un’alternativa ancora migliore.", "sections": [{"title": "Greedy", "text": "Scegli l’azione con la stima di valore più alta. Per pareggi, l’esercizio sceglie l’indice più piccolo.", "code": "azione = max(range(len(q)), key=lambda i: q[i])"}, {"title": "Epsilon-greedy", "text": "Con probabilità epsilon esplori; negli altri casi sfrutti la stima migliore. Qui il numero casuale viene dato come parametro, così puoi verificare ogni caso.", "code": "if random_value < epsilon:\n    return exploration_action\nreturn greedy_action"}, {"title": "UCB", "text": "UCB somma stima media e bonus di incertezza: media + c×sqrt(log(t)/n). t è il numero di tentativi totali, n quelli dell’azione. Se n=0 devi prima provare l’azione.", "code": ""}], "quiz": {"question": "Con epsilon=0.2 e random_value=0.1, cosa fai?", "choices": ["Esplori", "Scegli sempre l’azione migliore", "Interrompi l’episodio"], "answer": 0, "explanation": "0.1 è minore di 0.2, quindi questo tentativo ricade nell’esplorazione."}}, {"id": "q-learning", "track": "rl", "title": "Q-learning, senza saltare passaggi", "minutes": 6, "intro": "Q(s,a) è una stima di quanto conviene scegliere l’azione a nello stato s.", "sections": [{"title": "Costruisci il target", "text": "Parti dalla ricompensa r. Se l’episodio continua, aggiungi gamma × il più alto valore Q nello stato successivo. Se è finito, il target è solo r.", "code": "target = reward if done else reward + gamma * max(next_q)"}, {"title": "Misura quanto ti eri sbagliato", "text": "L’errore temporale è target − q_attuale. Se è positivo, avevi sottostimato il valore. Se è negativo, lo avevi sovrastimato.", "code": "errore = target - q_attuale"}, {"title": "Correggi solo una parte", "text": "Alpha, tra 0 e 1, stabilisce quanto della correzione accettare: q_nuovo = q_attuale + alpha × errore. Con q=2, target=6, alpha=0.25, arrivi a 3.", "code": "q_nuovo = q_attuale + alpha * (target - q_attuale)"}], "quiz": {"question": "Con q=2, target=6 e alpha=0.5, quanto vale q_nuovo?", "choices": ["6", "4", "3"], "answer": 1, "explanation": "L’errore è 4. Accetti metà della correzione: 2 + 0.5×4 = 4."}}, {"id": "text", "track": "automation", "title": "Testo e trasformazioni sicure", "minutes": 4, "intro": "Molte automazioni iniziano trasformando stringhe in dati coerenti.", "sections": [{"title": "Pulizia", "text": "strip elimina gli spazi esterni. lower rende il testo minuscolo. split separa le parole. Combinali solo quando la trasformazione ha senso per il tuo compito.", "code": "pulito = \"  Ciao  \".strip().lower()  # \"ciao\""}, {"title": "Estensioni e nomi", "text": "Una stringa può contenere più punti. rsplit(\".\", 1) divide a partire dall’ultimo; Path.suffix, nei progetti reali, rende esplicito il significato di estensione.", "code": "parti = \"report.finale.csv\".rsplit(\".\", 1)"}, {"title": "Non perdere informazioni", "text": "Un’automazione deve dire come gestisce valori vuoti e formati sconosciuti. Meglio una convenzione visibile che una trasformazione silenziosa.", "code": ""}], "quiz": {"question": "Cosa restituisce \" A B \".strip()?", "choices": ["\"AB\"", "\"A B\"", "\"a b\""], "answer": 1, "explanation": "strip rimuove solo gli spazi ai bordi, senza cambiare gli spazi interni o le maiuscole."}}, {"id": "formats", "track": "automation", "title": "CSV, JSON e regex", "minutes": 5, "intro": "I formati strutturati richiedono parser adatti: spezzare una stringa non sempre basta.", "sections": [{"title": "CSV", "text": "Una cella può contenere una virgola se è racchiusa tra virgolette. csv.DictReader gestisce queste regole e usa l’intestazione come chiavi.", "code": "import csv, io\nrighe = list(csv.DictReader(io.StringIO(testo_csv)))"}, {"title": "JSON", "text": "json.loads converte testo JSON in oggetti Python. json.dumps fa l’operazione inversa. Un booleano JSON true diventa True in Python.", "code": "import json\ndato = json.loads('{\"attivo\": true}')"}, {"title": "Regex", "text": "Una regex descrive un pattern. \\d riconosce una cifra; + ripete una o più volte. Una raw string evita che Python interpreti prima gli slash.", "code": "import re\nnumeri = re.findall(r\"\\d+\", \"ordine 12, lotto 7\")"}], "quiz": {"question": "Perché usare csv.DictReader invece di split(\",\")?", "choices": ["Gestisce anche separatori dentro celle quotate", "È sempre più corto", "Converte automaticamente ogni cella in numero"], "answer": 0, "explanation": "Il CSV ha regole di quoting; split non le interpreta. La conversione dei numeri resta esplicita."}}, {"id": "batch", "track": "automation", "title": "Pipeline, chunk e retry", "minutes": 5, "intro": "Una pipeline divide un compito grande in trasformazioni piccole e verificabili.", "sections": [{"title": "Lavora per blocchi", "text": "Un chunk è una porzione dei dati. Per dividere una lista in gruppi di k, parti dagli indici 0, k, 2k e prendi una slice di lunghezza k.", "code": "blocchi = [valori[i:i+k] for i in range(0, len(valori), k)]"}, {"title": "Conta gli esiti", "text": "Se ogni task ha un esito, puoi calcolare tasso di successo e latenza media separatamente. Un esito negativo non implica latenza zero.", "code": ""}, {"title": "Retry e backoff", "text": "Una sequenza di attese crescenti evita di riprovare continuamente. Un backoff esponenziale usa base×2^tentativo; un tetto limita l’attesa massima.", "code": "attesa = min(tetto, base * 2 ** tentativo)"}], "quiz": {"question": "Con base=2 e tentativi 0, 1, 2, quali sono le attese senza tetto?", "choices": ["[2, 4, 8]", "[0, 2, 4]", "[2, 3, 4]"], "answer": 0, "explanation": "Per tentativo 0 usi 2×1; poi 2×2 e 2×4."}}];
export const EXERCISES = [{"id": "python-doppio", "track": "python", "level": 1, "title": "Il tuo primo return", "lesson": "functions", "minutes": 4, "function": "doppio", "description": "Restituisci il doppio di numero. Il risultato deve essere restituito, non soltanto stampato.", "starter": "def doppio(numero):\n    # Scrivi qui la tua soluzione\n    pass", "solution": "def doppio(numero):\n    return numero * 2", "cases": [{"args": [4], "expected": 8}, {"args": [0], "expected": 0}, {"args": [-3], "expected": -6}, {"args": [2.5], "expected": 5}], "tips": ["Il doppio è il numero moltiplicato per 2.", "Usa return seguito dal calcolo."]}, {"id": "python-somma_lista", "track": "python", "level": 1, "title": "Una somma, tanti valori", "lesson": "loops", "minutes": 4, "function": "somma_lista", "description": "Restituisci la somma dei numeri di valori. Per una lista vuota restituisci 0.", "starter": "def somma_lista(valori):\n    # Scrivi qui la tua soluzione\n    pass", "solution": "def somma_lista(valori):\n    totale = 0\n    for x in valori:\n        totale += x\n    return totale", "cases": [{"args": [[1, 2, 3]], "expected": 6}, {"args": [[]], "expected": 0}, {"args": [[-4, 1]], "expected": -3}, {"args": [[2.5, 1.5]], "expected": 4}], "tips": ["Parti da un totale uguale a 0.", "Visita ogni numero e aggiungilo al totale. Anche sum(valori) è corretto."]}, {"id": "python-solo_pari", "track": "python", "level": 2, "title": "Il filtro dei numeri pari", "lesson": "loops", "minutes": 5, "function": "solo_pari", "description": "Restituisci una nuova lista con i numeri pari, nello stesso ordine. Zero e numeri negativi possono essere pari.", "starter": "def solo_pari(valori):\n    # Scrivi qui la tua soluzione\n    pass", "solution": "def solo_pari(valori):\n    return [x for x in valori if x % 2 == 0]", "cases": [{"args": [[1, 2, 3, 4]], "expected": [2, 4]}, {"args": [[]], "expected": []}, {"args": [[-2, -1, 0]], "expected": [-2, 0]}, {"args": [[7]], "expected": []}], "tips": ["Un numero è pari se il resto della divisione per 2 è 0.", "Puoi usare una comprehension con if x % 2 == 0."]}, {"id": "python-quadrati", "track": "python", "level": 2, "title": "Trasforma una lista", "lesson": "loops", "minutes": 5, "function": "quadrati", "description": "Restituisci il quadrato di ogni numero, mantenendo l’ordine.", "starter": "def quadrati(valori):\n    # Scrivi qui la tua soluzione\n    pass", "solution": "def quadrati(valori):\n    return [x ** 2 for x in valori]", "cases": [{"args": [[1, 2, 3]], "expected": [1, 4, 9]}, {"args": [[-2, 0]], "expected": [4, 0]}, {"args": [[]], "expected": []}, {"args": [[0.5]], "expected": [0.25]}], "tips": ["Il quadrato di x è x * x.", "Trasforma ogni elemento e raccogli i risultati in una nuova lista."]}, {"id": "python-frequenze", "track": "python", "level": 3, "title": "Quante volte compare?", "lesson": "dicts", "minutes": 6, "function": "frequenze", "description": "Restituisci un dizionario che conta ogni parola. Le parole sono già pulite e il confronto distingue maiuscole e minuscole.", "starter": "def frequenze(parole):\n    # Scrivi qui la tua soluzione\n    pass", "solution": "def frequenze(parole):\n    risultato = {}\n    for parola in parole:\n        risultato[parola] = risultato.get(parola, 0) + 1\n    return risultato", "cases": [{"args": [["a", "b", "a"]], "expected": {"a": 2, "b": 1}}, {"args": [[]], "expected": {}}, {"args": [["A", "a"]], "expected": {"A": 1, "a": 1}}], "tips": ["Usa le parole come chiavi di un dizionario.", "get(parola, 0) restituisce il vecchio conteggio o 0. Aggiungi 1."]}, {"id": "python-unici", "track": "python", "level": 3, "title": "Duplicati, senza perdere l’ordine", "lesson": "dicts", "minutes": 6, "function": "unici", "description": "Restituisci i numeri senza duplicati, mantenendo il primo incontro di ogni numero.", "starter": "def unici(valori):\n    # Scrivi qui la tua soluzione\n    pass", "solution": "def unici(valori):\n    visti = set()\n    risultato = []\n    for x in valori:\n        if x not in visti:\n            visti.add(x)\n            risultato.append(x)\n    return risultato", "cases": [{"args": [[3, 1, 3, 2, 1]], "expected": [3, 1, 2]}, {"args": [[]], "expected": []}, {"args": [[0, 0]], "expected": [0]}, {"args": [[-1, 2, -1]], "expected": [-1, 2]}], "tips": ["Una lista conserva l’ordine; un set ricorda i valori già visti.", "Aggiungi alla risposta solo quando il valore non è ancora nel set."]}, {"id": "python-raggruppa", "track": "python", "level": 4, "title": "Raggruppa per categoria", "lesson": "dicts", "minutes": 7, "function": "raggruppa", "description": "Ogni record contiene nome e categoria. Restituisci categoria → lista di nomi, conservando l’ordine dei record.", "starter": "def raggruppa(records):\n    # Scrivi qui la tua soluzione\n    pass", "solution": "def raggruppa(records):\n    gruppi = {}\n    for r in records:\n        gruppi.setdefault(r[\"categoria\"], []).append(r[\"nome\"])\n    return gruppi", "cases": [{"args": [[{"nome": "A", "categoria": "x"}, {"nome": "B", "categoria": "x"}, {"nome": "C", "categoria": "y"}]], "expected": {"x": ["A", "B"], "y": ["C"]}}, {"args": [[]], "expected": {}}, {"args": [[{"nome": "A", "categoria": "z"}]], "expected": {"z": ["A"]}}], "tips": ["Il valore di ogni chiave è una lista.", "setdefault(categoria, []) crea il gruppo se manca; poi append aggiunge il nome."]}, {"id": "python-appiattisci", "track": "python", "level": 4, "title": "Una lista di liste", "lesson": "advanced-python", "minutes": 7, "function": "appiattisci", "description": "Appiattisci esattamente un livello di annidamento. Ogni elemento di gruppi è una lista di numeri.", "starter": "def appiattisci(gruppi):\n    # Scrivi qui la tua soluzione\n    pass", "solution": "def appiattisci(gruppi):\n    return [x for gruppo in gruppi for x in gruppo]", "cases": [{"args": [[[1, 2], [3]]], "expected": [1, 2, 3]}, {"args": [[]], "expected": []}, {"args": [[[], [4], []]], "expected": [4]}], "tips": ["Servono due iterazioni: una sui gruppi e una sui numeri di ogni gruppo.", "Puoi usare extend su una lista risultato, una volta per gruppo."]}, {"id": "python-applica_offset", "track": "python", "level": 5, "title": "Una closure in azione", "lesson": "advanced-python", "minutes": 8, "function": "applica_offset", "description": "Crea una funzione interna che aggiunge offset. Applicala a ogni valore e restituisci la lista dei risultati. Il test verifica il risultato; prova a usare una closure per imparare il pattern.", "starter": "def applica_offset(valori, offset):\n    # Scrivi qui la tua soluzione\n    pass", "solution": "def applica_offset(valori, offset):\n    def aggiungi(x):\n        return x + offset\n    return [aggiungi(x) for x in valori]", "cases": [{"args": [[1, 2], 3], "expected": [4, 5]}, {"args": [[], -1], "expected": []}, {"args": [[0, -2], -3], "expected": [-3, -5]}], "tips": ["La funzione interna può usare offset senza riceverlo di nuovo.", "Definisci aggiungi(x), poi chiamala per ogni elemento."]}, {"id": "python-media_task", "track": "python", "level": 5, "title": "Riassumi i task riusciti", "lesson": "dicts", "minutes": 8, "function": "media_task", "description": "Ogni task contiene latency_s e passed. Restituisci {\"count\": numero di task riusciti, \"mean\": latenza media dei soli riusciti}. Se non ce ne sono, mean deve essere 0.0.", "starter": "def media_task(tasks):\n    # Scrivi qui la tua soluzione\n    pass", "solution": "def media_task(tasks):\n    ok = [t[\"latency_s\"] for t in tasks if t[\"passed\"]]\n    return {\"count\": len(ok), \"mean\": sum(ok) / len(ok) if ok else 0.0}", "cases": [{"args": [[{"latency_s": 2, "passed": true}, {"latency_s": 10, "passed": false}, {"latency_s": 4, "passed": true}]], "expected": {"count": 2, "mean": 3}}, {"args": [[]], "expected": {"count": 0, "mean": 0}}, {"args": [[{"latency_s": 5, "passed": false}]], "expected": {"count": 0, "mean": 0}}], "tips": ["Prima filtra i task con passed vero.", "Calcola conteggio e somma delle latenze filtrate. Gestisci il caso vuoto prima di dividere."]}, {"id": "algorithms-trova_indice", "track": "algorithms", "level": 1, "title": "Trova il primo incontro", "lesson": "search", "minutes": 4, "function": "trova_indice", "description": "Restituisci l’indice del primo obiettivo in valori. Se manca, restituisci -1. Gli indici iniziano da 0.", "starter": "def trova_indice(valori, obiettivo):\n    # Scrivi qui la tua soluzione\n    pass", "solution": "def trova_indice(valori, obiettivo):\n    for i, x in enumerate(valori):\n        if x == obiettivo:\n            return i\n    return -1", "cases": [{"args": [[4, 2, 4], 4], "expected": 0}, {"args": [[1, 2], 3], "expected": -1}, {"args": [[], 0], "expected": -1}, {"args": [[9], 9], "expected": 0}], "tips": ["enumerate dà indice e valore.", "Fermati con return al primo incontro. Dopo il ciclo restituisci -1."]}, {"id": "algorithms-palindromo", "track": "algorithms", "level": 1, "title": "Leggilo al contrario", "lesson": "search", "minutes": 4, "function": "palindromo", "description": "Restituisci True se testo è identico letto al contrario. Distingui maiuscole e spazi; la stringa vuota è un palindromo.", "starter": "def palindromo(testo):\n    # Scrivi qui la tua soluzione\n    pass", "solution": "def palindromo(testo):\n    return testo == testo[::-1]", "cases": [{"args": ["anna"], "expected": true}, {"args": ["python"], "expected": false}, {"args": [""], "expected": true}, {"args": ["Aa"], "expected": false}], "tips": ["Confronta il primo carattere con l’ultimo e continua verso il centro.", "La slice testo[::-1] inverte la stringa."]}, {"id": "algorithms-due_somme", "track": "algorithms", "level": 2, "title": "La coppia giusta", "lesson": "patterns", "minutes": 5, "function": "due_somme", "description": "Restituisci True se due elementi in posizioni diverse sommano a target. Non puoi usare lo stesso elemento due volte.", "starter": "def due_somme(valori, target):\n    # Scrivi qui la tua soluzione\n    pass", "solution": "def due_somme(valori, target):\n    visti = set()\n    for x in valori:\n        if target - x in visti:\n            return True\n        visti.add(x)\n    return False", "cases": [{"args": [[2, 7, 4], 9], "expected": true}, {"args": [[4], 8], "expected": false}, {"args": [[4, 4], 8], "expected": true}, {"args": [[], 0], "expected": false}], "tips": ["Se il numero corrente è x, cerchi target - x.", "Controlla il set prima di aggiungere x: così non riusi lo stesso elemento."]}, {"id": "algorithms-parentesi", "track": "algorithms", "level": 2, "title": "Parentesi in equilibrio", "lesson": "patterns", "minutes": 5, "function": "parentesi", "description": "testo contiene soltanto ( e ). Restituisci True se ogni apertura viene chiusa nell’ordine corretto. La stringa vuota è valida.", "starter": "def parentesi(testo):\n    # Scrivi qui la tua soluzione\n    pass", "solution": "def parentesi(testo):\n    aperte = 0\n    for c in testo:\n        aperte += 1 if c == \"(\" else -1\n        if aperte < 0:\n            return False\n    return aperte == 0", "cases": [{"args": ["(())"], "expected": true}, {"args": [")("], "expected": false}, {"args": ["(()"], "expected": false}, {"args": [""], "expected": true}], "tips": ["Conta quante aperture sono ancora da chiudere.", "Se il conteggio diventa negativo, una chiusura è arrivata troppo presto. Alla fine deve essere zero."]}, {"id": "algorithms-binaria", "track": "algorithms", "level": 3, "title": "Dimezza la ricerca", "lesson": "patterns", "minutes": 6, "function": "binaria", "description": "valori è ordinata e senza duplicati. Restituisci l’indice di target o -1 se manca. Prova a usare ricerca binaria.", "starter": "def binaria(valori, target):\n    # Scrivi qui la tua soluzione\n    pass", "solution": "def binaria(valori, target):\n    lo, hi = 0, len(valori) - 1\n    while lo <= hi:\n        mid = (lo + hi) // 2\n        if valori[mid] == target:\n            return mid\n        if valori[mid] < target:\n            lo = mid + 1\n        else:\n            hi = mid - 1\n    return -1", "cases": [{"args": [[1, 3, 5, 9], 5], "expected": 2}, {"args": [[1, 3], 2], "expected": -1}, {"args": [[], 1], "expected": -1}, {"args": [[2], 2], "expected": 0}], "tips": ["Mantieni un intervallo con due indici.", "Confronta l’elemento centrale. Escludilo quando sposti lo o hi, per far progredire il ciclo."]}, {"id": "algorithms-somma_finestra", "track": "algorithms", "level": 3, "title": "La finestra migliore", "lesson": "patterns", "minutes": 6, "function": "somma_finestra", "description": "Restituisci la massima somma di k elementi consecutivi. Se k non è tra 1 e len(valori), restituisci None.", "starter": "def somma_finestra(valori, k):\n    # Scrivi qui la tua soluzione\n    pass", "solution": "def somma_finestra(valori, k):\n    if k <= 0 or k > len(valori):\n        return None\n    totale = sum(valori[:k])\n    migliore = totale\n    for i in range(k, len(valori)):\n        totale += valori[i] - valori[i-k]\n        migliore = max(migliore, totale)\n    return migliore", "cases": [{"args": [[1, 4, 2, 8], 2], "expected": 10}, {"args": [[-5, -2, -3], 2], "expected": -5}, {"args": [[], 1], "expected": null}, {"args": [[1], 0], "expected": null}], "tips": ["Calcola la prima finestra. Poi togli il numero che esce e aggiungi quello che entra.", "Non inizializzare il massimo a 0: tutte le somme potrebbero essere negative."]}, {"id": "algorithms-fondi", "track": "algorithms", "level": 4, "title": "Fondi liste ordinate", "lesson": "patterns", "minutes": 7, "function": "fondi", "description": "Fondi due liste ordinate in una lista ordinata. Conserva tutti i duplicati. Prova a usare due puntatori.", "starter": "def fondi(a, b):\n    # Scrivi qui la tua soluzione\n    pass", "solution": "def fondi(a, b):\n    i = j = 0\n    out = []\n    while i < len(a) and j < len(b):\n        if a[i] <= b[j]:\n            out.append(a[i]); i += 1\n        else:\n            out.append(b[j]); j += 1\n    return out + a[i:] + b[j:]", "cases": [{"args": [[1, 3], [2, 4]], "expected": [1, 2, 3, 4]}, {"args": [[], [2]], "expected": [2]}, {"args": [[1, 1], [1]], "expected": [1, 1, 1]}], "tips": ["Confronta il primo elemento non ancora usato di ciascuna lista.", "Quando una lista finisce, aggiungi tutti i valori rimasti nell’altra."]}, {"id": "algorithms-gradini", "track": "algorithms", "level": 4, "title": "Quanti modi per salire?", "lesson": "graphs", "minutes": 7, "function": "gradini", "description": "Puoi salire 1 o 2 gradini alla volta. Restituisci il numero di sequenze per raggiungere n gradini, con n >= 0. Per n=0 conta la sequenza vuota: 1 modo.", "starter": "def gradini(n):\n    # Scrivi qui la tua soluzione\n    pass", "solution": "def gradini(n):\n    a, b = 1, 1\n    for _ in range(n):\n        a, b = b, a + b\n    return a", "cases": [{"args": [0], "expected": 1}, {"args": [1], "expected": 1}, {"args": [4], "expected": 5}, {"args": [6], "expected": 13}], "tips": ["L’ultimo passo arriva da n-1 o n-2.", "Somma le risposte dei due casi precedenti. Parti da modi(0)=1 e modi(1)=1."]}, {"id": "algorithms-distanza_bfs", "track": "algorithms", "level": 5, "title": "Il percorso più corto", "lesson": "graphs", "minutes": 8, "function": "distanza_bfs", "description": "grafo è un dizionario nodo → lista di vicini. Restituisci il numero minimo di archi tra inizio e fine, o -1 se fine non è raggiungibile. Da un nodo a se stesso la distanza è 0.", "starter": "def distanza_bfs(grafo, inizio, fine):\n    # Scrivi qui la tua soluzione\n    pass", "solution": "def distanza_bfs(grafo, inizio, fine):\n    from collections import deque\n    coda = deque([(inizio, 0)])\n    visti = {inizio}\n    while coda:\n        nodo, distanza = coda.popleft()\n        if nodo == fine:\n            return distanza\n        for vicino in grafo.get(nodo, []):\n            if vicino not in visti:\n                visti.add(vicino)\n                coda.append((vicino, distanza+1))\n    return -1", "cases": [{"args": [{"a": ["b"], "b": ["c"], "c": []}, "a", "c"], "expected": 2}, {"args": [{"a": ["a"]}, "a", "b"], "expected": -1}, {"args": [{}, "x", "x"], "expected": 0}, {"args": [{"a": ["b", "c"], "b": ["d"], "c": ["d"], "d": []}, "a", "d"], "expected": 2}], "tips": ["Usa una coda con coppie nodo, distanza.", "Segna i nodi visitati quando entrano in coda. Un set evita i cicli."]}, {"id": "algorithms-top_k", "track": "algorithms", "level": 5, "title": "I k valori più grandi", "lesson": "graphs", "minutes": 8, "function": "top_k", "description": "Restituisci i k valori più grandi in ordine decrescente, conservando i duplicati. Se k <= 0 restituisci []; se k supera la lunghezza, restituisci tutti i valori.", "starter": "def top_k(valori, k):\n    # Scrivi qui la tua soluzione\n    pass", "solution": "def top_k(valori, k):\n    import heapq\n    return heapq.nlargest(max(0, k), valori)", "cases": [{"args": [[3, 1, 7, 7, 2], 3], "expected": [7, 7, 3]}, {"args": [[2], 5], "expected": [2]}, {"args": [[1, 2], 0], "expected": []}, {"args": [[], 2], "expected": []}], "tips": ["La risposta finale è ordinata dal più grande al più piccolo.", "sorted(valori, reverse=True)[:max(0, k)] è una base corretta. heapq.nlargest è un’alternativa."]}, {"id": "data-media", "track": "data", "level": 1, "title": "Il centro dei dati", "lesson": "statistics", "minutes": 4, "function": "media", "description": "Restituisci la media dei valori; per la lista vuota restituisci 0.0.", "starter": "def media(valori):\n    # Scrivi qui la tua soluzione\n    pass", "solution": "def media(valori):\n    return sum(valori) / len(valori) if valori else 0.0", "cases": [{"args": [[2, 4, 6]], "expected": 4}, {"args": [[]], "expected": 0}, {"args": [[-2, 2]], "expected": 0}, {"args": [[1, 2]], "expected": 1.5}], "tips": ["La media è somma divisa per conteggio.", "Controlla prima se la lista è vuota, per evitare divisione per zero."]}, {"id": "data-rimuovi_mancanti", "track": "data", "level": 1, "title": "Il dato che manca", "lesson": "statistics", "minutes": 4, "function": "rimuovi_mancanti", "description": "Restituisci una lista senza i valori None. Conserva zero, False e stringhe vuote: non sono valori mancanti in questo esercizio.", "starter": "def rimuovi_mancanti(valori):\n    # Scrivi qui la tua soluzione\n    pass", "solution": "def rimuovi_mancanti(valori):\n    return [x for x in valori if x is not None]", "cases": [{"args": [[1, null, 0]], "expected": [1, 0]}, {"args": [[false, "", null]], "expected": [false, ""]}, {"args": [[]], "expected": []}], "tips": ["Usa un confronto esplicito con None.", "if x scarterebbe anche zero e False. Usa if x is not None."]}, {"id": "data-scala_array", "track": "data", "level": 2, "title": "La prima operazione NumPy", "lesson": "numpy", "minutes": 5, "function": "scala_array", "description": "Moltiplica ogni elemento di valori per fattore e restituisci una normale lista Python. Prova a usare un array NumPy.", "starter": "def scala_array(valori, fattore):\n    # Scrivi qui la tua soluzione\n    pass", "solution": "def scala_array(valori, fattore):\n    import numpy as np\n    return (np.array(valori) * fattore).tolist()", "cases": [{"args": [[1, 2, 3], 2], "expected": [2, 4, 6]}, {"args": [[], -1], "expected": []}, {"args": [[-2, 0], 0.5], "expected": [-1, 0]}], "tips": ["Una lista Python * 2 viene ripetuta; un array NumPy * 2 moltiplica i valori.", "Crea np.array(valori), moltiplicalo e termina con .tolist()."]}, {"id": "data-sopra_soglia", "track": "data", "level": 2, "title": "Una maschera sui dati", "lesson": "numpy", "minutes": 5, "function": "sopra_soglia", "description": "Restituisci i valori strettamente maggiori di soglia, conservando l’ordine. Prova a usare una maschera NumPy.", "starter": "def sopra_soglia(valori, soglia):\n    # Scrivi qui la tua soluzione\n    pass", "solution": "def sopra_soglia(valori, soglia):\n    import numpy as np\n    a = np.array(valori)\n    return a[a > soglia].tolist()", "cases": [{"args": [[1, 4, 2, 5], 2], "expected": [4, 5]}, {"args": [[], 0], "expected": []}, {"args": [[2, 2], 2], "expected": []}], "tips": ["Il confronto a > soglia crea una maschera booleana.", "Usa a[maschera] per selezionare gli elementi. La soglia stessa non va inclusa."]}, {"id": "data-minmax", "track": "data", "level": 3, "title": "Tutto tra zero e uno", "lesson": "scaling", "minutes": 6, "function": "minmax", "description": "Normalizza ogni valore con (x-min)/(max-min). Se tutti i valori coincidono restituisci zeri; una lista vuota restituisce [].", "starter": "def minmax(valori):\n    # Scrivi qui la tua soluzione\n    pass", "solution": "def minmax(valori):\n    if not valori:\n        return []\n    lo, hi = min(valori), max(valori)\n    return [(x-lo)/(hi-lo) for x in valori] if hi != lo else [0.0]*len(valori)", "cases": [{"args": [[10, 20, 30]], "expected": [0, 0.5, 1]}, {"args": [[4, 4]], "expected": [0, 0]}, {"args": [[]], "expected": []}, {"args": [[-3, -1]], "expected": [0, 1]}], "tips": ["Prima sposta il minimo a zero, poi dividi per l’ampiezza.", "Gestisci hi == lo prima di dividere."]}, {"id": "data-media_colonne", "track": "data", "level": 3, "title": "Scegli l’asse giusto", "lesson": "numpy", "minutes": 6, "function": "media_colonne", "description": "matrice è una matrice rettangolare non vuota. Restituisci la media di ogni colonna come lista.", "starter": "def media_colonne(matrice):\n    # Scrivi qui la tua soluzione\n    pass", "solution": "def media_colonne(matrice):\n    import numpy as np\n    return np.array(matrice).mean(axis=0).tolist()", "cases": [{"args": [[[1, 2], [3, 4]]], "expected": [2, 3]}, {"args": [[[2, 4, 6]]], "expected": [2, 4, 6]}, {"args": [[[0], [6], [3]]], "expected": [3]}], "tips": ["Devi combinare i valori verticalmente, colonna per colonna.", "In NumPy, mean(axis=0) riduce le righe."]}, {"id": "data-varianza", "track": "data", "level": 4, "title": "Misura la dispersione", "lesson": "statistics", "minutes": 7, "function": "varianza", "description": "Restituisci la varianza della popolazione: media dei quadrati degli scarti dalla media. Per la lista vuota restituisci 0.0.", "starter": "def varianza(valori):\n    # Scrivi qui la tua soluzione\n    pass", "solution": "def varianza(valori):\n    if not valori:\n        return 0.0\n    m = sum(valori)/len(valori)\n    return sum((x-m)**2 for x in valori)/len(valori)", "cases": [{"args": [[1, 3]], "expected": 1}, {"args": [[2, 2]], "expected": 0}, {"args": [[]], "expected": 0}, {"args": [[2, 4, 6]], "expected": 2.6666666666666665}], "tips": ["Calcola prima la media.", "Il denominatore qui è n, non n-1: si tratta della varianza della popolazione."]}, {"id": "data-medie_gruppo", "track": "data", "level": 4, "title": "Riassumi le categorie", "lesson": "scaling", "minutes": 7, "function": "medie_gruppo", "description": "Ogni record ha gruppo e valore. Restituisci un dizionario con la media per ogni gruppo. I gruppi sono stringhe.", "starter": "def medie_gruppo(records):\n    # Scrivi qui la tua soluzione\n    pass", "solution": "def medie_gruppo(records):\n    gruppi = {}\n    for r in records:\n        gruppi.setdefault(r[\"gruppo\"], []).append(r[\"valore\"])\n    return {k: sum(v)/len(v) for k,v in gruppi.items()}", "cases": [{"args": [[{"gruppo": "a", "valore": 2}, {"gruppo": "a", "valore": 4}, {"gruppo": "b", "valore": 8}]], "expected": {"a": 3, "b": 8}}, {"args": [[]], "expected": {}}, {"args": [[{"gruppo": "x", "valore": 0}]], "expected": {"x": 0}}], "tips": ["Raggruppa prima i valori per chiave.", "Puoi conservare le liste oppure una coppia somma, conteggio per gruppo."]}, {"id": "data-zscore", "track": "data", "level": 5, "title": "Quante deviazioni dal centro?", "lesson": "scaling", "minutes": 8, "function": "zscore", "description": "Calcola lo z-score di ogni valore usando la deviazione standard della popolazione. Per dati costanti restituisci zeri; per una lista vuota [].", "starter": "def zscore(valori):\n    # Scrivi qui la tua soluzione\n    pass", "solution": "def zscore(valori):\n    import numpy as np\n    if not valori:\n        return []\n    a = np.array(valori, dtype=float)\n    s = a.std()\n    return ((a-a.mean())/s).tolist() if s else [0.0]*len(valori)", "cases": [{"args": [[1, 3]], "expected": [-1, 1]}, {"args": [[4, 4]], "expected": [0, 0]}, {"args": [[]], "expected": []}, {"args": [[0, 2, 4]], "expected": [-1.224744871391589, 0, 1.224744871391589]}], "tips": ["La deviazione standard è la radice della varianza.", "np.std usa ddof=0 per impostazione predefinita, cioè la popolazione."]}, {"id": "data-prodotto_matrici", "track": "data", "level": 5, "title": "Il prodotto giusto", "lesson": "numpy", "minutes": 8, "function": "prodotto_matrici", "description": "a e b sono matrici compatibili non vuote. Restituisci il prodotto matriciale come lista di liste. Non fare il prodotto elemento per elemento.", "starter": "def prodotto_matrici(a, b):\n    # Scrivi qui la tua soluzione\n    pass", "solution": "def prodotto_matrici(a, b):\n    import numpy as np\n    return (np.array(a) @ np.array(b)).tolist()", "cases": [{"args": [[[1, 2], [3, 4]], [[1, 0], [0, 1]]], "expected": [[1, 2], [3, 4]]}, {"args": [[[1, 2, 3]], [[1], [2], [3]]], "expected": [[14]]}, {"args": [[[2]], [[3]]], "expected": [[6]]}], "tips": ["Ogni cella è il prodotto scalare di una riga di a e una colonna di b.", "In NumPy @ fa il prodotto matriciale; * moltiplica elemento per elemento."]}, {"id": "ml-accuracy", "track": "ml", "level": 1, "title": "Quanto ci azzecca?", "lesson": "metrics", "minutes": 4, "function": "accuracy", "description": "Restituisci la frazione di previsioni corrette. reali e previsti hanno la stessa lunghezza. Se sono vuote restituisci 0.0.", "starter": "def accuracy(reali, previsti):\n    # Scrivi qui la tua soluzione\n    pass", "solution": "def accuracy(reali, previsti):\n    return sum(a == b for a,b in zip(reali,previsti))/len(reali) if reali else 0.0", "cases": [{"args": [[1, 0, 1], [1, 1, 1]], "expected": 0.6666666666666666}, {"args": [[], []], "expected": 0}, {"args": [[0], [0]], "expected": 1}], "tips": ["Conta gli elementi uguali nella stessa posizione.", "zip unisce le coppie; dividi il numero di coppie corrette per il totale."]}, {"id": "ml-predict_linear", "track": "ml", "level": 1, "title": "Una retta che predice", "lesson": "regression", "minutes": 4, "function": "predict_linear", "description": "Restituisci le previsioni w*x+b per tutti gli ingressi xs.", "starter": "def predict_linear(xs, w, b):\n    # Scrivi qui la tua soluzione\n    pass", "solution": "def predict_linear(xs, w, b):\n    return [w*x+b for x in xs]", "cases": [{"args": [[1, 2, 3], 2, 1], "expected": [3, 5, 7]}, {"args": [[], 1, 0], "expected": []}, {"args": [[-1, 0], -2, 3], "expected": [5, 3]}], "tips": ["Ogni ingresso ha una previsione indipendente.", "Per ogni x moltiplica per w e poi aggiungi b."]}, {"id": "ml-mse", "track": "ml", "level": 2, "title": "Gli errori al quadrato", "lesson": "metrics", "minutes": 5, "function": "mse", "description": "Restituisci il mean squared error. Le liste hanno la stessa lunghezza; se vuote restituisci 0.0.", "starter": "def mse(reali, previsti):\n    # Scrivi qui la tua soluzione\n    pass", "solution": "def mse(reali, previsti):\n    return sum((p-y)**2 for y,p in zip(reali,previsti))/len(reali) if reali else 0.0", "cases": [{"args": [[1, 3], [2, 1]], "expected": 2.5}, {"args": [[], []], "expected": 0}, {"args": [[2], [2]], "expected": 0}, {"args": [[-1], [1]], "expected": 4}], "tips": ["Calcola gli scarti per ogni coppia.", "Eleva ogni scarto al quadrato prima di sommare e dividere per il conteggio."]}, {"id": "ml-split_train", "track": "ml", "level": 2, "title": "Separa train e test", "lesson": "classification", "minutes": 5, "function": "split_train", "description": "Mantieni l’ordine di valori. Prendi i primi int(len(valori)*frazione) elementi per il train, gli altri per il test. Restituisci [train, test]. frazione è tra 0 e 1.", "starter": "def split_train(valori, frazione):\n    # Scrivi qui la tua soluzione\n    pass", "solution": "def split_train(valori, frazione):\n    n = int(len(valori)*frazione)\n    return [valori[:n], valori[n:]]", "cases": [{"args": [[1, 2, 3, 4], 0.5], "expected": [[1, 2], [3, 4]]}, {"args": [[], 0.8], "expected": [[], []]}, {"args": [[1, 2, 3], 1], "expected": [[1, 2, 3], []]}, {"args": [[1, 2, 3], 0], "expected": [[], [1, 2, 3]]}], "tips": ["int tronca la parte decimale; qui tutti i conteggi sono non negativi.", "Usa due slice che si incontrano nello stesso indice n."]}, {"id": "ml-precision_recall", "track": "ml", "level": 3, "title": "Due modi di sbagliare", "lesson": "metrics", "minutes": 6, "function": "precision_recall", "description": "Le etichette sono 0 o 1. Restituisci {\"precision\": TP/(TP+FP), \"recall\": TP/(TP+FN)}. Un denominatore zero deve produrre 0.0.", "starter": "def precision_recall(reali, previsti):\n    # Scrivi qui la tua soluzione\n    pass", "solution": "def precision_recall(reali, previsti):\n    tp = sum(y == 1 and p == 1 for y,p in zip(reali,previsti))\n    fp = sum(y == 0 and p == 1 for y,p in zip(reali,previsti))\n    fn = sum(y == 1 and p == 0 for y,p in zip(reali,previsti))\n    return {\"precision\": tp/(tp+fp) if tp+fp else 0.0, \"recall\": tp/(tp+fn) if tp+fn else 0.0}", "cases": [{"args": [[1, 1, 0], [1, 0, 1]], "expected": {"precision": 0.5, "recall": 0.5}}, {"args": [[0, 0], [0, 0]], "expected": {"precision": 0, "recall": 0}}, {"args": [[1, 1], [1, 1]], "expected": {"precision": 1, "recall": 1}}], "tips": ["Prima conta TP, FP e FN separatamente.", "Precision riguarda ciò che hai chiamato positivo; recall riguarda i veri positivi disponibili."]}, {"id": "ml-gradiente_peso", "track": "ml", "level": 3, "title": "Deriva il peso di una retta", "lesson": "regression", "minutes": 6, "function": "gradiente_peso", "description": "Per il modello y_hat=w*x+b, restituisci il gradiente della MSE rispetto a w: (2/n)*somma((y_hat-y)*x). xs e ys hanno stessa lunghezza; se vuote restituisci 0.0.", "starter": "def gradiente_peso(xs, ys, w, b):\n    # Scrivi qui la tua soluzione\n    pass", "solution": "def gradiente_peso(xs, ys, w, b):\n    return 2*sum((w*x+b-y)*x for x,y in zip(xs,ys))/len(xs) if xs else 0.0", "cases": [{"args": [[1, 2], [2, 4], 0, 0], "expected": -10}, {"args": [[1, 2], [2, 4], 2, 0], "expected": 0}, {"args": [[], [], 0, 0], "expected": 0}], "tips": ["Per ogni esempio calcola prima previsione e errore.", "Moltiplica l’errore per x, somma, poi moltiplica per 2/n."]}, {"id": "ml-passo_regressione", "track": "ml", "level": 4, "title": "Un passo di training", "lesson": "regression", "minutes": 7, "function": "passo_regressione", "description": "Restituisci [nuovo_w, nuovo_b] dopo un passo sulla MSE. grad_w=(2/n)*somma(errore*x), grad_b=(2/n)*somma(errore). Usa gli stessi w e b originali per entrambi i gradienti. Le liste sono non vuote.", "starter": "def passo_regressione(xs, ys, w, b, lr):\n    # Scrivi qui la tua soluzione\n    pass", "solution": "def passo_regressione(xs, ys, w, b, lr):\n    errori = [w*x+b-y for x,y in zip(xs,ys)]\n    gw = 2*sum(e*x for e,x in zip(errori,xs))/len(xs)\n    gb = 2*sum(errori)/len(xs)\n    return [w-lr*gw, b-lr*gb]", "cases": [{"args": [[1, 2], [2, 4], 0, 0, 0.1], "expected": [1, 0.6]}, {"args": [[1], [3], 1, 1, 0.5], "expected": [2, 2]}, {"args": [[1], [2], 2, 0, 0.1], "expected": [2, 0]}], "tips": ["Calcola tutti gli errori con i parametri originali.", "Aggiorna entrambi i parametri sottraendo lr * il proprio gradiente."]}, {"id": "ml-knn_1d", "track": "ml", "level": 4, "title": "Chiedi ai vicini", "lesson": "classification", "minutes": 7, "function": "knn_1d", "description": "points e labels hanno uguale lunghezza. Prendi i k punti più vicini a x e restituisci l’etichetta più frequente. In parità di distanza prevale l’indice originale; in parità di voti prevale l’etichetta numerica più piccola. 1 <= k <= len(points).", "starter": "def knn_1d(points, labels, x, k):\n    # Scrivi qui la tua soluzione\n    pass", "solution": "def knn_1d(points, labels, x, k):\n    from collections import Counter\n    indici = sorted(range(len(points)), key=lambda i: (abs(points[i]-x), i))[:k]\n    voti = Counter(labels[i] for i in indici)\n    return min(voti, key=lambda label: (-voti[label], label))", "cases": [{"args": [[0, 1, 5], [0, 0, 1], 0.8, 2], "expected": 0}, {"args": [[0, 2], [1, 0], 1, 1], "expected": 1}, {"args": [[0, 2], [1, 0], 1, 2], "expected": 0}], "tips": ["Ordina gli indici per distanza, poi vota tra i primi k.", "Usa una chiave (-conteggio, etichetta) per risolvere il pareggio nei voti."]}, {"id": "ml-train_linear", "track": "ml", "level": 5, "title": "Impara la retta", "lesson": "regression", "minutes": 8, "function": "train_linear", "description": "Parti da w=0 e b=0. Esegui steps passi di discesa del gradiente sulla MSE e restituisci [w,b]. Usa lr come learning rate. xs e ys sono non vuote.", "starter": "def train_linear(xs, ys, lr, steps):\n    # Scrivi qui la tua soluzione\n    pass", "solution": "def train_linear(xs, ys, lr, steps):\n    w = b = 0.0\n    for _ in range(steps):\n        err = [w*x+b-y for x,y in zip(xs,ys)]\n        gw = 2*sum(e*x for e,x in zip(err,xs))/len(xs)\n        gb = 2*sum(err)/len(xs)\n        w, b = w-lr*gw, b-lr*gb\n    return [w,b]", "cases": [{"args": [[1], [2], 0.1, 1], "expected": [0.4, 0.4]}, {"args": [[1], [2], 0.1, 2], "expected": [0.64, 0.64]}, {"args": [[1, 2], [2, 4], 0.1, 0], "expected": [0, 0]}], "tips": ["Ripeti il passo già visto, ma parti da parametri zero.", "In ogni passo calcola entrambi i gradienti prima di aggiornare w e b."]}, {"id": "ml-confusion", "track": "ml", "level": 5, "title": "La matrice degli errori", "lesson": "metrics", "minutes": 8, "function": "confusion", "description": "Etichette binarie: restituisci [[TN, FP], [FN, TP]]. reali e previsti hanno stessa lunghezza.", "starter": "def confusion(reali, previsti):\n    # Scrivi qui la tua soluzione\n    pass", "solution": "def confusion(reali, previsti):\n    matrice = [[0,0],[0,0]]\n    for y,p in zip(reali,previsti):\n        matrice[y][p] += 1\n    return matrice", "cases": [{"args": [[0, 0, 1, 1], [0, 1, 0, 1]], "expected": [[1, 1], [1, 1]]}, {"args": [[], []], "expected": [[0, 0], [0, 0]]}, {"args": [[1, 1], [1, 1]], "expected": [[0, 0], [0, 2]]}], "tips": ["La riga indica l’etichetta vera e la colonna quella prevista.", "Incrementa matrice[y][p] per ogni coppia."]}, {"id": "dl-relu", "track": "dl", "level": 1, "title": "Accendi solo i positivi", "lesson": "neurons", "minutes": 4, "function": "relu", "description": "Applica ReLU a ogni valore: max(0,x). Restituisci la lista.", "starter": "def relu(valori):\n    # Scrivi qui la tua soluzione\n    pass", "solution": "def relu(valori):\n    return [max(0,x) for x in valori]", "cases": [{"args": [[-2, 0, 3]], "expected": [0, 0, 3]}, {"args": [[]], "expected": []}, {"args": [[0.5]], "expected": [0.5]}], "tips": ["I negativi diventano zero.", "Applica max(0,x) a ogni elemento."]}, {"id": "dl-dot", "track": "dl", "level": 1, "title": "La somma pesata", "lesson": "neurons", "minutes": 4, "function": "dot", "description": "Restituisci il prodotto scalare di a e b. Le liste hanno la stessa lunghezza; se vuote restituisci 0.", "starter": "def dot(a, b):\n    # Scrivi qui la tua soluzione\n    pass", "solution": "def dot(a, b):\n    return sum(x*y for x,y in zip(a,b))", "cases": [{"args": [[2, 3], [1, 2]], "expected": 8}, {"args": [[], []], "expected": 0}, {"args": [[-1, 2], [3, 4]], "expected": 5}], "tips": ["Moltiplica gli elementi nella stessa posizione.", "Somma i prodotti, non le liste di partenza."]}, {"id": "dl-sigmoid", "track": "dl", "level": 2, "title": "Da numero a probabilità", "lesson": "neurons", "minutes": 5, "function": "sigmoid", "description": "Restituisci sigmoid(x)=1/(1+exp(-x)). Gestisci anche valori grandi positivi e negativi senza overflow.", "starter": "def sigmoid(x):\n    # Scrivi qui la tua soluzione\n    pass", "solution": "def sigmoid(x):\n    import math\n    if x >= 0:\n        return 1/(1+math.exp(-x))\n    e = math.exp(x)\n    return e/(1+e)", "cases": [{"args": [0], "expected": 0.5}, {"args": [1], "expected": 0.7310585786300049}, {"args": [1000], "expected": 1}, {"args": [-1000], "expected": 0}], "tips": ["Per x positivo, exp(-x) è sicuro.", "Per x negativo usa la forma equivalente exp(x)/(1+exp(x))."]}, {"id": "dl-neurone", "track": "dl", "level": 2, "title": "Il tuo primo neurone", "lesson": "neurons", "minutes": 5, "function": "neurone", "description": "Restituisci ReLU(somma(x_i*w_i)+bias). x e w hanno la stessa lunghezza.", "starter": "def neurone(x, w, bias):\n    # Scrivi qui la tua soluzione\n    pass", "solution": "def neurone(x, w, bias):\n    return max(0, sum(a*b for a,b in zip(x,w))+bias)", "cases": [{"args": [[2, 3], [1, 2], 1], "expected": 9}, {"args": [[1], [-2], 0], "expected": 0}, {"args": [[], [], 3], "expected": 3}], "tips": ["Prima fai il prodotto scalare, poi aggiungi bias.", "L’attivazione ReLU va applicata solo dopo la somma pesata."]}, {"id": "dl-softmax", "track": "dl", "level": 3, "title": "Punteggi che sommano a uno", "lesson": "probabilities", "minutes": 6, "function": "softmax", "description": "Restituisci la softmax dei logits. Sottrai il massimo per stabilità numerica. Una lista vuota restituisce [].", "starter": "def softmax(logits):\n    # Scrivi qui la tua soluzione\n    pass", "solution": "def softmax(logits):\n    import math\n    if not logits:\n        return []\n    m = max(logits)\n    e = [math.exp(x-m) for x in logits]\n    return [x/sum(e) for x in e]", "cases": [{"args": [[0, 0]], "expected": [0.5, 0.5]}, {"args": [[1000, 1000]], "expected": [0.5, 0.5]}, {"args": [[]], "expected": []}, {"args": [[1, 2]], "expected": [0.2689414213699951, 0.7310585786300049]}], "tips": ["Sottrai lo stesso massimo a tutti i logits.", "Calcola gli esponenziali una volta, poi dividi ogni valore per la loro somma."]}, {"id": "dl-binary_loss", "track": "dl", "level": 3, "title": "Quanto costa l’errore?", "lesson": "probabilities", "minutes": 6, "function": "binary_loss", "description": "Restituisci la media della cross-entropy binaria. Prima limita ogni p tra 1e-12 e 1-1e-12. Le liste hanno stessa lunghezza; se vuote restituisci 0.0.", "starter": "def binary_loss(labels, probabilities):\n    # Scrivi qui la tua soluzione\n    pass", "solution": "def binary_loss(labels, probabilities):\n    import math\n    if not labels:\n        return 0.0\n    ps = [min(max(p,1e-12),1-1e-12) for p in probabilities]\n    return -sum(y*math.log(p)+(1-y)*math.log(1-p) for y,p in zip(labels,ps))/len(labels)", "cases": [{"args": [[1, 0], [0.5, 0.5]], "expected": 0.6931471805599453}, {"args": [[], []], "expected": 0}, {"args": [[1], [1]], "expected": 1e-12}, {"args": [[0], [0]], "expected": 1e-12}], "tips": ["Se y=1, la loss è -log(p); se y=0, è -log(1-p).", "Usa math.log, il logaritmo naturale. Il clipping evita log(0)."]}, {"id": "dl-dense_relu", "track": "dl", "level": 4, "title": "Uno strato intero", "lesson": "backprop", "minutes": 7, "function": "dense_relu", "description": "Ogni riga di weights è il vettore dei pesi di un neurone. biases contiene un bias per neurone. Restituisci la lista delle uscite con ReLU. Le dimensioni sono compatibili.", "starter": "def dense_relu(x, weights, biases):\n    # Scrivi qui la tua soluzione\n    pass", "solution": "def dense_relu(x, weights, biases):\n    return [max(0,sum(a*b for a,b in zip(x,w))+bias) for w,bias in zip(weights,biases)]", "cases": [{"args": [[1, 2], [[1, 1], [-1, -1]], [0, 1]], "expected": [3, 0]}, {"args": [[2], [[3]], [1]], "expected": [7]}, {"args": [[1], [], []], "expected": []}], "tips": ["Ripeti il calcolo di un neurone per ogni riga dei pesi.", "Ogni riga ha il proprio bias; non sommare tra loro le uscite dei neuroni."]}, {"id": "dl-dropout", "track": "dl", "level": 4, "title": "Una maschera di training", "lesson": "backprop", "minutes": 7, "function": "dropout", "description": "Applica inverted dropout: uscita_i = valore_i * mask_i / keep. mask contiene 0 o 1, keep è tra 0 escluso e 1 incluso. Restituisci la lista.", "starter": "def dropout(valori, mask, keep):\n    # Scrivi qui la tua soluzione\n    pass", "solution": "def dropout(valori, mask, keep):\n    return [x*m/keep for x,m in zip(valori,mask)]", "cases": [{"args": [[1, 2, 3], [1, 0, 1], 0.5], "expected": [2, 0, 6]}, {"args": [[2], [1], 1], "expected": [2]}, {"args": [[], [], 0.5], "expected": []}], "tips": ["La maschera azzera i valori da eliminare.", "Dividi i valori rimasti per keep per conservare la media attesa."]}, {"id": "dl-passo_logistico", "track": "dl", "level": 5, "title": "Backprop per un neurone", "lesson": "backprop", "minutes": 8, "function": "passo_logistico", "description": "Un neurone sigmoid usa z=w*x+b e cross-entropy binaria. Calcola p in modo stabile, poi aggiorna w e b: grad_w=(p-y)*x, grad_b=p-y. Restituisci [nuovo_w, nuovo_b].", "starter": "def passo_logistico(x, y, w, b, lr):\n    # Scrivi qui la tua soluzione\n    pass", "solution": "def passo_logistico(x, y, w, b, lr):\n    import math\n    z = w*x+b\n    p = 1/(1+math.exp(-z)) if z >= 0 else math.exp(z)/(1+math.exp(z))\n    e = p-y\n    return [w-lr*e*x, b-lr*e]", "cases": [{"args": [2, 1, 0, 0, 0.1], "expected": [0.1, 0.05]}, {"args": [2, 0, 0, 0, 0.1], "expected": [-0.1, -0.05]}, {"args": [0, 1, 0, 0, 0], "expected": [0, 0]}], "tips": ["Calcola p dai parametri originali.", "Lo stesso errore p-y serve a entrambi i gradienti, ma per w devi moltiplicarlo per x."]}, {"id": "dl-gradiente_relu", "track": "dl", "level": 5, "title": "Un gradiente attraverso ReLU", "lesson": "backprop", "minutes": 8, "function": "gradiente_relu", "description": "Ricevi i valori prima della ReLU e i gradienti in uscita. Restituisci i gradienti in ingresso: grad_i se pre_i > 0, altrimenti 0. A zero usiamo convenzionalmente derivata 0.", "starter": "def gradiente_relu(pre, grad):\n    # Scrivi qui la tua soluzione\n    pass", "solution": "def gradiente_relu(pre, grad):\n    return [g if z > 0 else 0 for z,g in zip(pre,grad)]", "cases": [{"args": [[-1, 0, 2], [3, 4, 5]], "expected": [0, 0, 5]}, {"args": [[2], [-3]], "expected": [-3]}, {"args": [[], []], "expected": []}], "tips": ["La derivata della ReLU è 1 nella parte positiva e 0 nella parte negativa.", "Moltiplica il gradiente in uscita per questa derivata. A zero segui la convenzione indicata."]}, {"id": "rl-somma_reward", "track": "rl", "level": 1, "title": "Il risultato dell’episodio", "lesson": "rewards", "minutes": 4, "function": "somma_reward", "description": "Restituisci la somma delle ricompense di un episodio, senza sconto. Una lista vuota vale 0.", "starter": "def somma_reward(rewards):\n    # Scrivi qui la tua soluzione\n    pass", "solution": "def somma_reward(rewards):\n    return sum(rewards)", "cases": [{"args": [[1, -1, 3]], "expected": 3}, {"args": [[]], "expected": 0}, {"args": [[-2, -3]], "expected": -5}], "tips": ["Le ricompense possono essere negative.", "Qui non c’è gamma: basta la somma delle ricompense."]}, {"id": "rl-greedy", "track": "rl", "level": 1, "title": "Scegli l’azione migliore", "lesson": "exploration", "minutes": 4, "function": "greedy", "description": "q è una lista non vuota di valori delle azioni. Restituisci l’indice del valore più alto. In parità scegli l’indice più piccolo.", "starter": "def greedy(q):\n    # Scrivi qui la tua soluzione\n    pass", "solution": "def greedy(q):\n    return max(range(len(q)), key=lambda i: q[i])", "cases": [{"args": [[1, 4, 2]], "expected": 1}, {"args": [[3, 3]], "expected": 0}, {"args": [[-5, -2]], "expected": 1}], "tips": ["Devi restituire la posizione, non il valore.", "max su range(len(q)) con key trova l’indice. Il primo massimo risolve il pareggio."]}, {"id": "rl-discounted", "track": "rl", "level": 2, "title": "Le ricompense future contano meno", "lesson": "rewards", "minutes": 5, "function": "discounted", "description": "Restituisci r0 + gamma*r1 + gamma**2*r2 + ... . gamma è tra 0 e 1. La lista vuota vale 0.", "starter": "def discounted(rewards, gamma):\n    # Scrivi qui la tua soluzione\n    pass", "solution": "def discounted(rewards, gamma):\n    totale = 0\n    for r in reversed(rewards):\n        totale = r + gamma*totale\n    return totale", "cases": [{"args": [[1, 2, 4], 0.5], "expected": 3}, {"args": [[2, 4], 0], "expected": 2}, {"args": [[], 0.9], "expected": 0}, {"args": [[1, 2], 1], "expected": 3}], "tips": ["Il primo elemento ha peso 1.", "Puoi sommare r * gamma**i oppure procedere a ritroso con totale = r + gamma*totale."]}, {"id": "rl-epsilon_greedy", "track": "rl", "level": 2, "title": "Un po’ di esplorazione", "lesson": "exploration", "minutes": 5, "function": "epsilon_greedy", "description": "Se random_value < epsilon restituisci exploration_action. Altrimenti restituisci l’indice del massimo di q, con pareggio a favore dell’indice minore. q non è vuota e exploration_action è valido.", "starter": "def epsilon_greedy(q, epsilon, random_value, exploration_action):\n    # Scrivi qui la tua soluzione\n    pass", "solution": "def epsilon_greedy(q, epsilon, random_value, exploration_action):\n    if random_value < epsilon:\n        return exploration_action\n    return max(range(len(q)), key=lambda i: q[i])", "cases": [{"args": [[1, 5], 0.2, 0.1, 0], "expected": 0}, {"args": [[1, 5], 0.2, 0.3, 0], "expected": 1}, {"args": [[4, 4], 0.2, 0.2, 1], "expected": 0}], "tips": ["Il confronto è strettamente minore.", "Il numero casuale è fornito dall’esercizio: non generarne un altro."]}, {"id": "rl-media_incrementale", "track": "rl", "level": 3, "title": "Impara una ricompensa alla volta", "lesson": "exploration", "minutes": 6, "function": "media_incrementale", "description": "q è la vecchia media di n osservazioni. Restituisci la nuova media dopo aver osservato reward: q + (reward-q)/(n+1). n è almeno 0.", "starter": "def media_incrementale(q, n, reward):\n    # Scrivi qui la tua soluzione\n    pass", "solution": "def media_incrementale(q, n, reward):\n    return q + (reward-q)/(n+1)", "cases": [{"args": [2, 2, 5], "expected": 3}, {"args": [0, 0, 4], "expected": 4}, {"args": [3, 3, 3], "expected": 3}], "tips": ["Dopo l’osservazione, il conteggio totale è n+1.", "Muovi la vecchia stima verso la nuova ricompensa di una frazione 1/(n+1)."]}, {"id": "rl-q_update", "track": "rl", "level": 3, "title": "Correggi il valore di un’azione", "lesson": "q-learning", "minutes": 6, "function": "q_update", "description": "Restituisci q + alpha*(target-q). Se done è True, target=reward; altrimenti target=reward+gamma*max(next_q). next_q può essere vuota soltanto quando done=True.", "starter": "def q_update(q, reward, next_q, alpha, gamma, done):\n    # Scrivi qui la tua soluzione\n    pass", "solution": "def q_update(q, reward, next_q, alpha, gamma, done):\n    target = reward if done else reward + gamma*max(next_q)\n    return q + alpha*(target-q)", "cases": [{"args": [2, 1, [4, 3], 0.5, 0.5, false], "expected": 2.5}, {"args": [2, 6, [], 0.25, 0.9, true], "expected": 3}, {"args": [1, 0, [5], 0, 0.9, false], "expected": 1}], "tips": ["Calcola prima il target, poi l’errore target-q.", "Quando done è vero non usare next_q: non esistono ricompense future."]}, {"id": "rl-bellman", "track": "rl", "level": 4, "title": "Un backup di valore", "lesson": "q-learning", "minutes": 7, "function": "bellman", "description": "Ogni transizione contiene [probabilità, reward, valore_successivo, done]. Restituisci la somma di p*(reward + gamma*valore_successivo) per le transizioni non terminali e p*reward per quelle terminali.", "starter": "def bellman(transizioni, gamma):\n    # Scrivi qui la tua soluzione\n    pass", "solution": "def bellman(transizioni, gamma):\n    return sum(p*(r if done else r+gamma*v) for p,r,v,done in transizioni)", "cases": [{"args": [[[0.5, 2, 4, false], [0.5, 0, 8, true]], 0.5], "expected": 2}, {"args": [[], 0.9], "expected": 0}, {"args": [[[1, 3, 100, true]], 0.9], "expected": 3}], "tips": ["Ogni esito contribuisce in proporzione alla propria probabilità.", "Per done=True elimina la parte di valore futuro, anche se il parametro è non zero."]}, {"id": "rl-ucb", "track": "rl", "level": 4, "title": "Il bonus dell’incertezza", "lesson": "exploration", "minutes": 7, "function": "ucb", "description": "Restituisci l’indice che massimizza media_i + c*sqrt(log(t)/count_i). Se esistono conteggi zero, scegli il primo indice con zero. In parità scegli l’indice minore. t>=1, le liste sono non vuote.", "starter": "def ucb(medie, counts, t, c):\n    # Scrivi qui la tua soluzione\n    pass", "solution": "def ucb(medie, counts, t, c):\n    import math\n    for i,n in enumerate(counts):\n        if n == 0:\n            return i\n    scores = [m+c*math.sqrt(math.log(t)/n) for m,n in zip(medie,counts)]\n    return max(range(len(scores)), key=lambda i:scores[i])", "cases": [{"args": [[2, 1], [3, 0], 3, 1], "expected": 1}, {"args": [[1, 1], [10, 1], 11, 1], "expected": 1}, {"args": [[4, 4], [2, 2], 4, 0], "expected": 0}], "tips": ["Un’azione mai provata va esplorata prima di applicare la formula.", "Il bonus è più grande per le azioni con meno osservazioni."]}, {"id": "rl-returns", "track": "rl", "level": 5, "title": "Un ritorno per ogni passo", "lesson": "rewards", "minutes": 8, "function": "returns", "description": "Restituisci una lista con il ritorno scontato a partire da ogni posizione. Per rewards=[1,2,4] e gamma=0.5 il risultato è [3,4,4].", "starter": "def returns(rewards, gamma):\n    # Scrivi qui la tua soluzione\n    pass", "solution": "def returns(rewards, gamma):\n    out = []\n    g = 0\n    for r in reversed(rewards):\n        g = r+gamma*g\n        out.append(g)\n    return out[::-1]", "cases": [{"args": [[1, 2, 4], 0.5], "expected": [3, 4, 4]}, {"args": [[], 0.9], "expected": []}, {"args": [[1, 2], 0], "expected": [1, 2]}], "tips": ["Calcola a ritroso e memorizza ogni valore intermedio.", "La lista costruita a ritroso va invertita prima di restituirla."]}, {"id": "rl-policy_eval", "track": "rl", "level": 5, "title": "Valuta una politica", "lesson": "q-learning", "minutes": 8, "function": "policy_eval", "description": "P è una matrice di probabilità tra stati, rewards la ricompensa immediata per stato. Parti da valori tutti zero e fai iterations aggiornamenti sincroni: nuovo_v[i]=rewards[i]+gamma*somma(P[i][j]*v[j]). Restituisci i valori finali. Dimensioni compatibili.", "starter": "def policy_eval(P, rewards, gamma, iterations):\n    # Scrivi qui la tua soluzione\n    pass", "solution": "def policy_eval(P, rewards, gamma, iterations):\n    v = [0.0]*len(rewards)\n    for _ in range(iterations):\n        v = [rewards[i]+gamma*sum(p*x for p,x in zip(row,v)) for i,row in enumerate(P)]\n    return v", "cases": [{"args": [[[1]], [2], 0.5, 2], "expected": [3]}, {"args": [[[0, 1], [0, 1]], [1, 2], 0.5, 2], "expected": [2, 3]}, {"args": [[[1]], [2], 0.5, 0], "expected": [0]}], "tips": ["Ogni iterazione deve leggere solo i valori dell’iterazione precedente.", "Crea una lista nuova; aggiornarla elemento per elemento sul posto cambierebbe l’algoritmo."]}, {"id": "automation-pulisci", "track": "automation", "level": 1, "title": "Nomi puliti", "lesson": "text", "minutes": 4, "function": "pulisci", "description": "Rimuovi gli spazi ai bordi e converti in minuscolo ciascun nome. Conserva gli spazi interni. Restituisci la lista.", "starter": "def pulisci(nomi):\n    # Scrivi qui la tua soluzione\n    pass", "solution": "def pulisci(nomi):\n    return [n.strip().lower() for n in nomi]", "cases": [{"args": [[" Anna ", "BOB"]], "expected": ["anna", "bob"]}, {"args": [[]], "expected": []}, {"args": [[" A B "]], "expected": ["a b"]}], "tips": ["strip e lower svolgono due compiti diversi.", "Applica entrambe le trasformazioni a ogni stringa."]}, {"id": "automation-solo_csv", "track": "automation", "level": 1, "title": "Scegli i file CSV", "lesson": "text", "minutes": 4, "function": "solo_csv", "description": "Restituisci i nomi che finiscono con .csv, senza distinguere maiuscole e minuscole. Mantieni i nomi originali e l’ordine.", "starter": "def solo_csv(nomi):\n    # Scrivi qui la tua soluzione\n    pass", "solution": "def solo_csv(nomi):\n    return [n for n in nomi if n.lower().endswith(\".csv\")]", "cases": [{"args": [["a.csv", "b.txt", "C.CSV"]], "expected": ["a.csv", "C.CSV"]}, {"args": [[]], "expected": []}, {"args": [["csv", "a.csv.tmp"]], "expected": []}], "tips": ["Normalizza solo il confronto, senza cambiare la risposta.", "endswith(\".csv\") evita di includere a.csv.tmp."]}, {"id": "automation-estrai_numeri", "track": "automation", "level": 2, "title": "Numeri dentro il testo", "lesson": "formats", "minutes": 5, "function": "estrai_numeri", "description": "Estrai tutte le sequenze di cifre e restituiscile come interi nell’ordine del testo. Un segno meno non fa parte del numero in questo esercizio.", "starter": "def estrai_numeri(testo):\n    # Scrivi qui la tua soluzione\n    pass", "solution": "def estrai_numeri(testo):\n    import re\n    return [int(x) for x in re.findall(r\"\\d+\",testo)]", "cases": [{"args": ["ordine 12, lotto 7"], "expected": [12, 7]}, {"args": ["nessuno"], "expected": []}, {"args": ["A003 -4"], "expected": [3, 4]}], "tips": ["Una regex può riconoscere una o più cifre consecutive.", "Usa re.findall(r\"\\d+\", testo), poi converti i risultati con int."]}, {"id": "automation-chunk", "track": "automation", "level": 2, "title": "Piccoli blocchi", "lesson": "batch", "minutes": 5, "function": "chunk", "description": "Dividi valori in liste di dimensione massima k. k è positivo; l’ultimo blocco può essere più piccolo.", "starter": "def chunk(valori, k):\n    # Scrivi qui la tua soluzione\n    pass", "solution": "def chunk(valori, k):\n    return [valori[i:i+k] for i in range(0,len(valori),k)]", "cases": [{"args": [[1, 2, 3, 4, 5], 2], "expected": [[1, 2], [3, 4], [5]]}, {"args": [[], 3], "expected": []}, {"args": [[1], 5], "expected": [[1]]}], "tips": ["Gli indici di partenza avanzano di k.", "La slice i:i+k si ferma automaticamente alla fine della lista."]}, {"id": "automation-csv_totale", "track": "automation", "level": 3, "title": "Un report CSV", "lesson": "formats", "minutes": 6, "function": "csv_totale", "description": "testo contiene CSV con intestazione prodotto,quantita,prezzo. Restituisci la somma di quantita*prezzo per ogni riga. I numeri usano il punto decimale. Le celle possono essere quotate.", "starter": "def csv_totale(testo):\n    # Scrivi qui la tua soluzione\n    pass", "solution": "def csv_totale(testo):\n    import csv, io\n    return sum(int(r[\"quantita\"])*float(r[\"prezzo\"]) for r in csv.DictReader(io.StringIO(testo)))", "cases": [{"args": ["prodotto,quantita,prezzo\na,2,3.5\nb,1,2\n"], "expected": 9}, {"args": ["prodotto,quantita,prezzo\n"], "expected": 0}, {"args": ["prodotto,quantita,prezzo\n\"a,b\",2,4\n"], "expected": 8}], "tips": ["Usa il parser csv: un nome può contenere una virgola.", "DictReader produce stringhe. Converti quantita e prezzo prima del prodotto."]}, {"id": "automation-json_attivi", "track": "automation", "level": 3, "title": "Leggi una configurazione", "lesson": "formats", "minutes": 6, "function": "json_attivi", "description": "testo è un array JSON di oggetti con nome e attivo. Restituisci i nomi degli oggetti con attivo=true.", "starter": "def json_attivi(testo):\n    # Scrivi qui la tua soluzione\n    pass", "solution": "def json_attivi(testo):\n    import json\n    return [r[\"nome\"] for r in json.loads(testo) if r[\"attivo\"]]", "cases": [{"args": ["[{\"nome\":\"A\",\"attivo\":true},{\"nome\":\"B\",\"attivo\":false}]"], "expected": ["A"]}, {"args": ["[]"], "expected": []}, {"args": ["[{\"nome\":\"C\",\"attivo\":true}]"], "expected": ["C"]}], "tips": ["Prima converti il testo JSON in una lista Python.", "json.loads interpreta true come True. Poi filtra per il campo attivo."]}, {"id": "automation-backoff", "track": "automation", "level": 4, "title": "Riprova con calma", "lesson": "batch", "minutes": 7, "function": "backoff", "description": "Restituisci una lista di attempts attese: min(cap, base*2**i), per i da 0 a attempts-1. attempts è almeno 0 e base, cap sono positivi.", "starter": "def backoff(base, cap, attempts):\n    # Scrivi qui la tua soluzione\n    pass", "solution": "def backoff(base, cap, attempts):\n    return [min(cap,base*2**i) for i in range(attempts)]", "cases": [{"args": [2, 10, 5], "expected": [2, 4, 8, 10, 10]}, {"args": [1, 100, 0], "expected": []}, {"args": [5, 3, 2], "expected": [3, 3]}], "tips": ["Il primo tentativo usa esponente 0, quindi fattore 1.", "Applica il tetto a ogni singola attesa."]}, {"id": "automation-riepilogo", "track": "automation", "level": 4, "title": "Un cruscotto per i task", "lesson": "batch", "minutes": 7, "function": "riepilogo", "description": "Ogni task ha passed e latency_s. Restituisci {\"success_rate\": frazione dei task riusciti, \"mean_latency\": latenza media di TUTTI i task}. Se la lista è vuota entrambi i valori sono 0.0.", "starter": "def riepilogo(tasks):\n    # Scrivi qui la tua soluzione\n    pass", "solution": "def riepilogo(tasks):\n    if not tasks:\n        return {\"success_rate\":0.0,\"mean_latency\":0.0}\n    return {\"success_rate\":sum(t[\"passed\"] for t in tasks)/len(tasks),\"mean_latency\":sum(t[\"latency_s\"] for t in tasks)/len(tasks)}", "cases": [{"args": [[{"passed": true, "latency_s": 2}, {"passed": false, "latency_s": 6}]], "expected": {"success_rate": 0.5, "mean_latency": 4}}, {"args": [[]], "expected": {"success_rate": 0, "mean_latency": 0}}, {"args": [[{"passed": true, "latency_s": 0}]], "expected": {"success_rate": 1, "mean_latency": 0}}], "tips": ["Success rate e latenza media hanno conteggi diversi al numeratore.", "Non filtrare le latenze per passed: il testo chiede la media di tutti i task."]}, {"id": "automation-flatten_config", "track": "automation", "level": 5, "title": "Una configurazione piatta", "lesson": "formats", "minutes": 8, "function": "flatten_config", "description": "Appiattisci un dizionario JSON annidato usando punti tra i nomi delle chiavi. Solo i dizionari sono annidati; liste, numeri, stringhe e booleani restano valori finali. I dizionari vuoti non generano voci.", "starter": "def flatten_config(config):\n    # Scrivi qui la tua soluzione\n    pass", "solution": "def flatten_config(config):\n    risultato = {}\n    def visita(d, prefix):\n        for k,v in d.items():\n            nome = prefix+\".\"+k if prefix else k\n            if isinstance(v,dict):\n                visita(v,nome)\n            else:\n                risultato[nome] = v\n    visita(config,\"\")\n    return risultato", "cases": [{"args": [{"db": {"host": "local", "port": 42}, "debug": true}], "expected": {"db.host": "local", "db.port": 42, "debug": true}}, {"args": [{}], "expected": {}}, {"args": [{"x": {"y": {"z": 1}}, "a": [1, 2], "vuoto": {}}], "expected": {"x.y.z": 1, "a": [1, 2]}}], "tips": ["Visita ricorsivamente soltanto i valori che sono dizionari.", "Passa un prefisso alla chiamata ricorsiva. Le liste non devono essere esplorate."]}, {"id": "automation-join_records", "track": "automation", "level": 5, "title": "Unisci due sorgenti", "lesson": "dicts", "minutes": 8, "function": "join_records", "description": "Unisci users e scores tramite id. Ogni user ha id e nome; ogni score ha id e score. Restituisci i record degli utenti con uno score, in ordine di users, con chiavi id,nome,score. Gli id sono unici in ogni lista.", "starter": "def join_records(users, scores):\n    # Scrivi qui la tua soluzione\n    pass", "solution": "def join_records(users, scores):\n    lookup = {s[\"id\"]:s[\"score\"] for s in scores}\n    return [{\"id\":u[\"id\"],\"nome\":u[\"nome\"],\"score\":lookup[u[\"id\"]]} for u in users if u[\"id\"] in lookup]", "cases": [{"args": [[{"id": 1, "nome": "A"}, {"id": 2, "nome": "B"}], [{"id": 2, "score": 8}]], "expected": [{"id": 2, "nome": "B", "score": 8}]}, {"args": [[], []], "expected": []}, {"args": [[{"id": 1, "nome": "A"}], [{"id": 1, "score": 0}]], "expected": [{"id": 1, "nome": "A", "score": 0}]}], "tips": ["Costruisci un dizionario id → score per la ricerca.", "Verifica la presenza dell’id, non la verità dello score: uno score di 0 è valido."]}];
